mapper.select:
SELECT id, tenant_code, doc_id, chunk_no, content, char_count, token_count,
       embedding_model, create_time
  FROM kb_chunk
 WHERE tenant_code = #{tenantCode}
   AND doc_id = #{docId}
 ORDER BY chunk_no
 LIMIT #{limit}

mapper.delete:
DELETE FROM kb_chunk
 WHERE tenant_code = #{tenantCode}
   AND doc_id = #{docId}
